#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
int main() {
    int t; scanf("%d", &t);
    while (t--) {
        ll n, k; scanf("%lld %lld", &n, &k);
        vector<ll> a(n);
        ll total = 0;
        for (auto &x : a) { scanf("%lld", &x); total += x; }
        sort(a.rbegin(), a.rend());              // largest counts get the extra copy
        auto feasible = [&](ll x) {               // can we make x full windows?
            ll L = n + x - 1, q = L / n, r = L % n, cost = 0;
            for (ll i = 0; i < n; i++) {
                ll need = q + (i < r ? 1 : 0);
                cost += max(0LL, need - a[i]);
                if (cost > k) return false;
            }
            return true;
        };
        ll lo = 0, hi = total + k - n + 1;
        if (hi < 0) hi = 0;
        while (lo < hi) {                          // largest feasible x
            ll mid = lo + (hi - lo + 1) / 2;
            if (feasible(mid)) lo = mid; else hi = mid - 1;
        }
        printf("%lld\n", lo);
    }
}
